import raw from "../data/voiceover.generated.json";

export type Token = { text: string; full: string; start: number; end: number; color: string; latin: boolean };
export type Phrase = { seg: string; start: number; end: number; tokens: Token[] };
export type Segment = { id: string; srcStart: number; srcEnd: number; placeAt: number; endAt: number; text: string };

/** Generated by `npm run captions` from the voiceover word timestamps. */
export const voice = raw as unknown as { duration: number; segments: Segment[]; phrases: Phrase[] };
